html:
{# =========================================================
   Fleet Card Issued (Jinja Print Format)
   Same styling technique as Vehicle Allocation Handover (rounded-corner
   tables via border-collapse:separate + border-radius+overflow:hidden,
   accent callout boxes, table-based signature block - wkhtmltopdf has poor
   flexbox support, so the table-based signature block is a correctness
   fix as well as a style match).
   ========================================================= #}

{% set company = frappe.db.get_value("Asset", doc.fleet_number, "company") %}
{% set letter_head_name = frappe.db.get_value("Company", company, "default_letter_head") if company else None %}
{% set lh = frappe.db.get_value("Letter Head", letter_head_name, ["source", "content", "image"], as_dict=True) if letter_head_name else None %}

<style>
  @media print { @page { size: A4 portrait; margin: 10mm; } }
  * { box-sizing: border-box; }
  body { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #222222; }

  .fci-letterhead { text-align: center; margin-bottom: 14px; }
  .fci-letterhead img { max-height: 70px; }

  .fci-title { text-align: center; font-size: 18px; font-weight: 700; margin: 0 0 2px; color: #1565c0; }
  .fci-subtitle { text-align: center; font-size: 11px; color: #555555; margin: 0 0 14px; }

  .fci-section-title {
    margin: 20px 0 8px; padding-bottom: 4px; border-bottom: 1px solid #1565c0;
    font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px;
    color: #1565c0; page-break-after: avoid;
  }

  .fci-callout {
    margin: 0 0 10px; padding: 9px 11px; border: 1px solid #d8d8d8; border-left: 4px solid #1565c0;
    border-radius: 6px; background: #fafafa; color: #555555; line-height: 1.4; page-break-inside: avoid;
  }

  table.fci-table {
    width: 100%; border-collapse: separate; border-spacing: 0; border: 1px solid #dddddd;
    border-radius: 8px; overflow: hidden; margin-bottom: 4px;
  }
  table.fci-table th, table.fci-table td {
    padding: 6px 8px; font-size: 10.5px; text-align: left; vertical-align: top;
    border-right: 1px solid #dddddd; border-bottom: 1px solid #dddddd;
  }
  table.fci-table th { background: #f5f5f5; font-weight: 700; }
  table.fci-table th:last-child, table.fci-table td:last-child { border-right: none; }
  table.fci-table tbody tr:last-child td { border-bottom: none; }
  table.fci-table tbody tr:nth-child(odd) td { background: #fafafa; }
  table.fci-table tr { page-break-inside: avoid; }

  table.fci-caps td.fci-check-col { text-align: center; width: 70px; font-size: 14px; }

  .fci-signatures { margin-top: 10px; page-break-inside: auto; }
  .fci-signatures table { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .fci-signatures tr { page-break-inside: avoid; }
  .fci-signatures td { border: none; vertical-align: bottom; padding: 30px 20px 12px 0; }
  .fci-sig-line { height: 22px; border-bottom: 1px solid #222222; }
  .fci-sig-label { margin-top: 4px; font-size: 10px; color: #555555; }

  @page {
    @bottom-right { content: "Page " counter(page) " of " counter(pages); font-size: 9px; color: #999999; }
  }
</style>

{% if lh %}
<div class="fci-letterhead">
  {% if lh.source == "Image" and lh.image %}
    <img src="{{ frappe.utils.get_url(lh.image) }}">
  {% elif lh.content %}
    {{ lh.content }}
  {% endif %}
</div>
{% endif %}

<div class="fci-title">Fleet Card Issued</div>
<div class="fci-subtitle">{{ doc.name }} &middot; Issued {{ frappe.utils.formatdate(doc.issue_date) }}</div>

{% if doc.previous_fleet_card %}
<div class="fci-callout">This card replaces <strong>{{ doc.previous_fleet_card }}</strong>. Reason: {{ doc.comments or "—" }}</div>
{% endif %}

<div class="fci-section-title">Card &amp; Vehicle Details</div>
<table class="fci-table">
  <tr>
    <th style="width:18%;">Asset</th>
    <td style="width:32%;">{{ doc.fleet_number }}{% if doc.model %} - {{ doc.model }}{% endif %}</td>
    <th style="width:18%;">Registration Number</th>
    <td>{{ doc.registration_number or "—" }}</td>
  </tr>
  <tr>
    <th>Bank</th>
    <td>{{ doc.bank or "—" }}</td>
    <th>Card Number</th>
    <td>{{ doc.card_number }}</td>
  </tr>
  <tr>
    <th>Issue Date</th>
    <td>{{ frappe.utils.formatdate(doc.issue_date) if doc.issue_date else "—" }}</td>
    <th>Expiry Date</th>
    <td>{{ frappe.utils.formatdate(doc.expiry_date) }}</td>
  </tr>
  <tr>
    <th>Card Limit</th>
    <td>{{ frappe.utils.fmt_money(doc.card_limit, currency=frappe.db.get_value("Company", company, "default_currency")) if doc.card_limit else "—" }}</td>
    <th>Issued To</th>
    <td>{{ doc.issued_to_name or doc.issued_to or "—" }}</td>
  </tr>
</table>

<div class="fci-section-title">Card Capabilities</div>
<table class="fci-table fci-caps">
  <thead>
    <tr>
      <th>Fuel</th>
      <th>Toll</th>
      <th>Oil</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td class="fci-check-col">{{ "&#9745;" | safe if doc.covers_fuel else "&#9633;" | safe }}</td>
      <td class="fci-check-col">{{ "&#9745;" | safe if doc.covers_toll else "&#9633;" | safe }}</td>
      <td class="fci-check-col">{{ "&#9745;" | safe if doc.covers_oil else "&#9633;" | safe }}</td>
    </tr>
  </tbody>
</table>

<div class="fci-section-title">Sign-Off</div>
<div class="fci-callout">I confirm receipt of the above Fleet Card, in good working order, for use strictly in accordance with company policy. The signed copy of this document is the Attachment required to submit this record.</div>
<div class="fci-signatures">
  <table>
    <tr>
      <td>
        <div class="fci-sig-line"></div>
        <div class="fci-sig-label">{{ doc.issued_to_name or doc.issued_to or "Received By" }}<br>Signature &amp; Date</div>
      </td>
      <td>
        <div class="fci-sig-line"></div>
        <div class="fci-sig-label">Issued By (Manager)<br>Signature &amp; Date</div>
      </td>
    </tr>
  </table>
</div>
